		Path directory = Files.createDirectory(options.output.resolve(mode + "-" + scenario.name));
		LmdbStoreConfig config = new LmdbStoreConfig(INDEXES)
				.setForceSync(options.forceSync)
				.setAutoGrow(true)
				.setTripleDBSize(256L << 20)
				.setValueDBSize(256L << 20)
				.setDirectAdjacencyEnabled(false)
				.setSketchEstimatorEnabled(false)
				.setAsyncValueCleanup(asynchronous)
				.setAsyncValueCleanupAdmissionTimeoutMillis(options.admissionTimeoutMillis);
		if (scenario == Scenario.PRESSURE) {
			config.setAsyncValueCleanupMaxCandidates(2048)
					.setAsyncValueCleanupMaxBytes(256L << 10)
					.setAsyncValueCleanupBatchSize(128)
					.setAsyncValueCleanupMaxPendingProducers(4);
		}
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		List<Sample> recorded = new ArrayList<>();
		AllocationCounter allocations = new AllocationCounter();
		long scenarioAllocationStarted = allocations.jvm();
		AsyncValueRetirementCoordinator coordinator = null;
		LmdbSailStore backingStore = null;
		long measuredNanos = 0;
		long phaseAllocationBytes = -1;
		long shutdownAllocationBytes = -1;
		long drainNanos = 0;
		long shutdownNanos;
